'use strict';

const { Benchmark } = require('benchmark');

const kroniko = require('kroniko');
kroniko.install({
    std: false,
    sentry: {
        dsn: 'https://asdasdsaasd@127.0.0.2/1',
    },
});

const yandexLogger = require('..')({
    name: 'yandex-logger',
    middleware: [
        // отключаем все стандартные мидлвары
    ],
    streams: [
        {
            level: 'info',
            stream: require('../streams/sentry')({
                dsn: 'https://asdasdsaasd@127.0.0.2/1',
            }),
        },
    ],
});

const data = {
    x: 1,
    y: 2,
    z: {
        x: 1,
        y: 2,
        z: [1, 2],
    },
};
const message = 'Something bad!';
const err = new TypeError('undefined is not a function');

let suite = new Benchmark.Suite('Logger');
suite
    .add('[yandex-logger] Simple message', () => {
        yandexLogger.error(message);
    })
    .add('[kroniko] Simple message', () => {
        kroniko.error(message);
    })
    .add('[yandex-logger] Message and data', () => {
        yandexLogger.error({ data }, message);
    })
    .add('[kroniko] Message and data', () => {
        kroniko.error(message, data);
    })
    .add('[yandex-logger] Error', () => {
        yandexLogger.error(err);
    })
    .add('[kroniko] Error', () => {
        kroniko.error(err);
    })
    .on('cycle', event => console.warn(String(event.target)))
    .on('error', err => console.warn('Ошибка!', err))
    .run();
